const body = $input.first().json.body;
const campos = body.campos || {};
const out = { id: body.evento_id };
for (const key of Object.keys(campos)) {
    if (key === 'quando') {
          out.quando = DateTime.fromISO(campos.quando, { zone: 'Europe/Lisbon' }).toISO();
    } else {
          out[key] = campos[key];
    }
}
return [{ json: out }];
